106	    /**
107	     * Make this animal act - that is: make it do
108	     * whatever it wants/needs to do.
109	     * Checks if the time of day matches if the animal is nocturnal or not,
110	     * then attempts to find food and move.
111	     * @param newAnimals A list to receive newly born animals.
112	     * @param weather The weather condition of the simulation.
113	     */
114	    public void act(List<Actor> newAnimals, WeatherCond weather)
115	    {
116	        super.act(newAnimals,weather);
117	        incrementHunger();
118	        if(isAlive()&&(getTime().isDay() != nocturnal)) {
119	            giveBirth(newAnimals);            
120	            // Move towards a source of food if found.
121	            Location newLocation = null;
122	            if (getField().getWeatherAttributeValueAt(WeatherAttribute.VISIBILITY, getLocation()) > 0.4){
123	                newLocation = findFood();
124	            }
125	            if(newLocation == null) { 
126	                // No food found - try to move to a free location.
127	                newLocation = getField().freeAdjacentLocation(this, getLocation());
128	            }
129	            // See if it was possible to move.
130	            if(newLocation != null) {
131	                setLocation(newLocation);
132	            }
133	            else {
134	                // Overcrowding.
135	                setDead();
136	            }
137	        }
138	    }
