151	    /**
152	     * Checks if the animal is female and looks for a mate
153	     * @param newAnimals The List of new animals that have been born to add to the simulator List of actors
154	     */
155	    protected void giveBirth(List<Actor> newAnimals)
156	    {
157	        // New animals are born into adjacent locations.
158	        // Get a list of adjacent free locations.
159	        if (female&&findMate()) {
160	            super.giveBirth(newAnimals);
161	        }
162	    }
