164	    /**
165	     * Searches for a mate to breed with.
166	     * Searches first for an adjacent animal of the same dynamic type,
167	     * then if that animal is male.
168	     * @return true if a mate is found.
169	     */
170	    protected boolean findMate()
171	    {
172	        Field field = getField();
173	        List<Location> adjacent = field.adjacentLocations(getLocation());
174	        Iterator<Location> it = adjacent.iterator();
175	        while(it.hasNext()){
176	            Location where = it.next();
177	            Object actor = field.getObjectAt(where);
178	            if (actor instanceof Animal) {
179	                Animal animal = (Animal) actor;
180	                if (animal.getActorName().equals(getActorName())&& !animal.female){
181	                    giveDiseases(animal);
182	                    return true;
183	                }
184	            }
185	        }
186	        return false;
187	    }
188	
189	    /**
190	     * Transfer diseases from the male mate to the female and vice versa.
191	     * @param mate The male mate that the female breeds with.
192	     */
193	    protected void giveDiseases(Animal mate)
194	    {
195	        for (Disease disease: mate.setDiseases){
196	            if (disease.isSpreadByBirth()){
197	                setDiseases.add(disease);
198	            }
199	        }
200	        for (Disease disease: setDiseases){
201	            if (disease.isSpreadByBirth()){
202	                mate.getActorDiseaseSet().add(disease);
203	            }
204	        }
205	    }
206	
207	    /**
208	     * Look for rabbits adjacent to the current location.
209	     * Only the first live rabbit is eaten.
210	     * @return Where food was found, or null if it wasn't.
211	     */
212	    protected Location findFood()
213	    {
214	        Field field = getField();
215	        List<Location> adjacent = field.adjacentLocations(getLocation());
216	        Iterator<Location> it = adjacent.iterator();
217	        while(it.hasNext()) {
218	            Location where = it.next();
219	            if(canOccupy(where)) {
220	                Object actor = field.getObjectAt(where);
221	                if (actor instanceof Actor) {
222	                    Actor prey = (Actor) actor;
223	                    Integer foodValue = getPreyFoodValuesMap().get(prey.getActorName());
224	                    if(foodValue != null && prey.isAlive()) {
225	                        for (Disease disease: prey.setDiseases){
226	                            if (disease.isSpreadByEating() && disease.getActorsAffectedMap().containsKey(getActorName())){
227	                                setDiseases.add(disease);
228	                            }
229	                        }
230	                        prey.setDead();
231	                        foodLevel = Math.min(foodLevel + foodValue, getMaxFood());
232	                        return where;
233	                    }
234	                }
235	            }
236	        }
237	        return null;
238	    }
